# One-off cleanup for a database at Patch 68.
# Run with an existing postgres maintenance connection named `con`:
#   source("dev/remove_patch68_calm_wind_qc.R")
# This script never opens a connection or applies patches.
#
# Deletes qc_dir_calm assignments and its catalogue entry, ALL qualifiers
# (including UNS, UNK and protected qualifiers) on current wind-direction
# series, and their matching audit.general_log history. This includes audit
# rows generated by these deletions. Other rules and measurements are retained.
# Future imports may still supply qualifiers; other assigned QC rules may
# also write them. Removing the catalogue entry prevents qc_dir_calm from
# being selected again by populateTimeseriesQCRules().
#
# Everything commits together or rolls back. Blocks writes to the listed
# source tables until commit/rollback. Each lock wait is limited to 15 seconds
# and each statement to 5 minutes (these are not whole-script time limits).

local({
  stopifnot(DBI::dbIsValid(con))
  identity <- DBI::dbGetQuery(
    con,
    "SELECT session_user, current_user, current_database() AS database,
            inet_server_addr()::text AS server"
  )
  if (
    identity$session_user[[1L]] != "postgres" ||
      identity$current_user[[1L]] != "postgres"
  ) {
    stop("Use a postgres maintenance connection without SET ROLE.")
  }
  if (
    !identical(identity$server[[1L]], "199.247.132.26/32") ||
      !identical(identity$database[[1L]], "aquacache")
  ) {
    stop(
      "Expected the aquacache database on production host 199.247.132.26/32."
    )
  }
  if (AquaCache::dbTransCheck(con)) {
    stop("A transaction is already open. Commit or roll it back first.")
  }

  counts <- DBI::dbWithTransaction(con, {
    DBI::dbExecute(con, "SET LOCAL lock_timeout = '15s'")
    DBI::dbExecute(con, "SET LOCAL statement_timeout = '5min'")
    DBI::dbExecute(
      con,
      "LOCK TABLE public.parameters, continuous.timeseries,
         public.qc_rule_capabilities, continuous.timeseries_qc_rules,
         continuous.qualifiers IN SHARE ROW EXCLUSIVE MODE"
    )
    revision <- DBI::dbGetQuery(
      con,
      "SELECT version FROM information.version_info
       WHERE item = 'Last patch number'"
    )$version
    if (length(revision) != 1L || is.na(revision) || revision != "68") {
      stop("This one-off script requires a database at exactly Patch 68.")
    }

    # Capture the scope before deleting anything, including inactive series.
    # Use the exact parameter name used by Patch 68's population policy.
    DBI::dbExecute(
      con,
      "CREATE TEMP TABLE cleanup68_wind_series ON COMMIT DROP AS
       SELECT t.timeseries_id
       FROM continuous.timeseries t
       JOIN public.parameters p USING (parameter_id)
       WHERE p.param_name =
         'wind direction (direction from, expressed 0-360 deg)'"
    )
    DBI::dbExecute(
      con,
      "ALTER TABLE pg_temp.cleanup68_wind_series
       ADD PRIMARY KEY (timeseries_id)"
    )
    n_series <- DBI::dbGetQuery(
      con,
      "SELECT count(*)::integer AS n FROM pg_temp.cleanup68_wind_series"
    )$n[[1L]]
    if (n_series == 0L) {
      stop("No wind-direction series found; nothing was deleted.")
    }
    unexpected <- DBI::dbGetQuery(
      con,
      "SELECT EXISTS (
         SELECT 1 FROM continuous.timeseries_qc_rules r
         WHERE r.rule_fx = 'qc_dir_calm'
           AND NOT EXISTS (
             SELECT 1 FROM pg_temp.cleanup68_wind_series w
             WHERE w.timeseries_id = r.timeseries_id
           )
       ) AS found"
    )$found[[1L]]
    if (isTRUE(unexpected)) {
      stop(
        "qc_dir_calm is assigned outside wind direction; review those assignments first."
      )
    }

    # Delete children before the catalogue row to respect the foreign key.
    n_rules <- DBI::dbExecute(
      con,
      "DELETE FROM continuous.timeseries_qc_rules
       WHERE rule_fx = 'qc_dir_calm'"
    )
    n_catalogue <- DBI::dbExecute(
      con,
      "DELETE FROM public.qc_rule_capabilities
       WHERE rule_fx = 'qc_dir_calm'"
    )
    n_qualifiers <- DBI::dbExecute(
      con,
      "DELETE FROM continuous.qualifiers q
       USING pg_temp.cleanup68_wind_series w
       WHERE q.timeseries_id = w.timeseries_id"
    )
    # Flush deferred constraints/triggers before purging generated history.
    DBI::dbExecute(con, "SET CONSTRAINTS ALL IMMEDIATE")

    # These three tables write history only to audit.general_log.
    # Match BOTH payloads so UPDATE and DELETE history are covered, including
    # qualifiers already replaced/deleted during backfill. Never delete a
    # whole transaction's audit history: Patch 68 may have applied other rules.
    audit_scope <- "(
         l.schema_name = 'continuous' AND l.table_name = 'qualifiers'
         AND (
           (l.original_data ->> 'timeseries_id') IN (
             SELECT timeseries_id::text FROM pg_temp.cleanup68_wind_series
           ) OR (l.new_data ->> 'timeseries_id') IN (
             SELECT timeseries_id::text FROM pg_temp.cleanup68_wind_series
           )
         )
       ) OR (
         ((l.schema_name = 'continuous'
           AND l.table_name = 'timeseries_qc_rules')
          OR (l.schema_name = 'public'
              AND l.table_name = 'qc_rule_capabilities'))
         AND (l.original_data ->> 'rule_fx' = 'qc_dir_calm'
              OR l.new_data ->> 'rule_fx' = 'qc_dir_calm')
       )"
    n_audit <- DBI::dbExecute(
      con,
      sprintf("DELETE FROM audit.general_log l WHERE %s", audit_scope)
    )
    audit_remaining <- DBI::dbGetQuery(
      con,
      sprintf(
        "SELECT EXISTS (SELECT 1 FROM audit.general_log l WHERE %s) AS found",
        audit_scope
      )
    )$found[[1L]]

    remaining <- DBI::dbGetQuery(
      con,
      "SELECT
         EXISTS (SELECT 1 FROM continuous.timeseries_qc_rules
                 WHERE rule_fx = 'qc_dir_calm') AS assignments,
         EXISTS (SELECT 1 FROM public.qc_rule_capabilities
                 WHERE rule_fx = 'qc_dir_calm') AS catalogue,
         EXISTS (SELECT 1 FROM continuous.qualifiers q
                 JOIN pg_temp.cleanup68_wind_series w USING (timeseries_id))
           AS qualifiers"
    )
    if (isTRUE(audit_remaining) || any(unlist(remaining, use.names = FALSE))) {
      stop("Cleanup verification failed; rolling back.")
    }
    n_other_rules <- DBI::dbGetQuery(
      con,
      "SELECT count(*)::integer AS n
       FROM continuous.timeseries_qc_rules r
       JOIN pg_temp.cleanup68_wind_series w USING (timeseries_id)
       WHERE r.active"
    )$n[[1L]]
    data.frame(
      wind_direction_series = n_series,
      assignments_deleted = n_rules,
      catalogue_rows_deleted = n_catalogue,
      qualifiers_deleted = n_qualifiers,
      audit_rows_deleted = n_audit,
      other_active_wind_assignments = n_other_rules
    )
  })
  message(
    "Cleanup committed on ",
    identity$server[[1L]],
    " / ",
    identity$database[[1L]],
    "."
  )
  print(counts, row.names = FALSE)
  if (counts$other_active_wind_assignments[[1L]] > 0L) {
    message(
      "Other active wind-direction QC assignments remain and may generate new qualifiers."
    )
  }
})
